/* From Uiverse.io by NlghtM4re - Tags: progress, progress bar, loader, glow, bars, animated */
.__UIV_SCOPE__ .loader {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  position: relative;
}

.__UIV_SCOPE__ .loader:before {
  content: "";
  position: absolute;
  top: -10px;
  left: -10px;
  right: -10px;
  bottom: -10px;
  border-radius: 50%;
}

.__UIV_SCOPE__ .loader-inner {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.__UIV_SCOPE__ .loader-block {
  display: inline-block;
  width: 8px;
  height: 10px;
  margin: 2px;
  background-color: rgb(53, 143, 246);
  box-shadow: 0 0 30px rgb(53, 143, 246);
  animation: loader 5s infinite;
}

.__UIV_SCOPE__ .loader-block:nth-child(1) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .loader-block:nth-child(2) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .loader-block:nth-child(3) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loader-block:nth-child(4) {
  animation-delay: 0.8s;
}

.__UIV_SCOPE__ .loader-block:nth-child(5) {
  animation-delay: 1s;
}

.__UIV_SCOPE__ .loader-block:nth-child(6) {
  animation-delay: 1.2s;
}

.__UIV_SCOPE__ .loader-block:nth-child(7) {
  animation-delay: 1.4s;
}

.__UIV_SCOPE__ .loader-block:nth-child(8) {
  animation-delay: 1.6s;
}

.__UIV_SCOPE__ .loader-block:nth-child(9) {
  animation-delay: 1.8s;
}

.__UIV_SCOPE__ .loader-block:nth-child(10) {
  animation-delay: 2s;
}

.__UIV_SCOPE__ .loader-block:nth-child(11) {
  animation-delay: 2.2s;
}

.__UIV_SCOPE__ .loader-block:nth-child(12) {
  animation-delay: 2.4s;
}

.__UIV_SCOPE__ .loader-block:nth-child(13) {
  animation-delay: 2.6s;
}

.__UIV_SCOPE__ .loader-block:nth-child(14) {
  animation-delay: 2.8s;
}

.__UIV_SCOPE__ .loader-block:nth-child(15) {
  animation-delay: 3s;
}

.__UIV_SCOPE__ .loader-block:nth-child(16) {
  animation-delay: 3.2s;
}

.__UIV_SCOPE__ .loader-block:nth-child(17) {
  animation-delay: 3.4s;
}

.__UIV_SCOPE__ .loader-block:nth-child(18) {
  animation-delay: 3.6s;
}

.__UIV_SCOPE__ .loader-block:nth-child(19) {
  animation-delay: 3.8s;
}

.__UIV_SCOPE__ .loader-block:nth-child(20) {
  animation-delay: 4s;
}

.__UIV_SCOPE__ .loader-block:nth-child(21) {
  animation-delay: 4.2s;
}

.__UIV_SCOPE__ .loader-block:nth-child(22) {
  animation-delay: 4.4s;
}

.__UIV_SCOPE__ .loader-block:nth-child(23) {
  animation-delay: 4.6s;
}

.__UIV_SCOPE__ .loader-block:nth-child(24) {
  animation-delay: 4.8s;
}

@keyframes loader {
  0% {
    transform: scale(1);
    box-shadow: 0 0 40px rgb(53, 143, 246);
  }

  13% {
    transform: scale(1, 4);
    box-shadow: 0 0 60px rgb(53, 143, 246);
  }

  26% {
    transform: scale(1);
    box-shadow: 0 0 40px rgb(53, 143, 246);
  }
}
